import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Бэкенды рабочих пространств","description":"","frontmatter":{},"headers":[],"relativePath":"ru/self-hosted/workspace-backends.md","filePath":"ru/self-hosted/workspace-backends.md","lastUpdated":1792323081000}'),n={name:"ru/self-hosted/workspace-backends.md"};function l(o,s,d,p,h,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="бэкенды-рабочих-пространств" tabindex="-1">Бэкенды рабочих пространств <a class="header-anchor" href="#бэкенды-рабочих-пространств" aria-label="Permalink to &quot;Бэкенды рабочих пространств&quot;">​</a></h1><p>Каждый Bot в Memoh работает внутри рабочего пространства. Рабочим пространством может быть изолированный контейнер или, в доверенных настольных и локальных сценариях, локальный каталог на хосте. Бэкенд определяет, где выполняется это рабочее пространство и какие возможности изоляции, сети, снапшотов и дисплея доступны.</p><h2 id="контеинерные-бэкенды" tabindex="-1">Контейнерные бэкенды <a class="header-anchor" href="#контеинерные-бэкенды" aria-label="Permalink to &quot;Контейнерные бэкенды&quot;">​</a></h2><p>Контейнерные рабочие пространства настраиваются в <code>config.toml</code>:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # containerd, docker или apple</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Бэкенд</th><th>Для чего подходит</th><th>Примечания</th></tr></thead><tbody><tr><td><code>containerd</code></td><td>Серверные развёртывания на Docker Compose, серверы Linux, разработка</td><td>Используется по умолчанию в официальном образе сервера. Поддерживает сеть CNI, снапшоты, устройства CDI, сайдкары провайдеров и самый широкий набор возможностей локальных рабочих пространств.</td></tr><tr><td><code>docker</code></td><td>Развёртывания на хосте или из бинарника с Docker Engine</td><td>Использует Docker API хоста. Пути bind-монтирования рантайма вроде <code>container.runtime_dir</code> должны существовать на хосте с Docker.</td></tr><tr><td><code>apple</code></td><td>Локальное тестирование на macOS</td><td>Использует socktainer и Apple Containerization. Оверлейные сайдкары провайдеров не поддерживаются.</td></tr></tbody></table><p>Серверное развёртывание Docker Compose в одну команду использует <code>containerd</code>. Это сделано намеренно: образ сервера запускает встроенный containerd и монтирует файлы рантайма, нужные рабочим пространствам Bot. Остальные бэкенды используйте для ручных развёртываний, в которых пути рантайма на хосте контролируете вы.</p><h2 id="доверенные-локальные-рабочие-пространства" tabindex="-1">Доверенные локальные рабочие пространства <a class="header-anchor" href="#доверенные-локальные-рабочие-пространства" aria-label="Permalink to &quot;Доверенные локальные рабочие пространства&quot;">​</a></h2><p>В Desktop и при локальной разработке можно включить доверенные локальные рабочие пространства в дополнение к настроенному контейнерному бэкенду:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>Доверенные локальные рабочие пространства выполняются на хосте с правами процесса сервера. Они удобны для личных настольных сценариев и локальной разработки, но <strong>не изолированы контейнером</strong>. Не включайте локальные рабочие пространства в недоверенных серверных развёртываниях.</p><p>Когда Bot использует локальное рабочее пространство, элементы интерфейса, которым нужен контейнерный рабочий стол или контейнерная сессия дисплея, могут быть скрыты или недоступны.</p><h2 id="containerd" tabindex="-1">containerd <a class="header-anchor" href="#containerd" aria-label="Permalink to &quot;containerd&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_image = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;debian:bookworm-slim&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">image_pull_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;if_not_present&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">snapshotter = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;overlayfs&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data_root = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/data&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/runtime&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cni_bin_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/cni/bin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cni_conf_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/cni/net.d&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">containerd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socket_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/run/containerd/containerd.sock&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">namespace = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div><p>Используйте этот бэкенд для официального стека Docker Compose и для хостов, где Memoh может обращаться к containerd напрямую.</p><h2 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docker&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_image = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;debian:bookworm-slim&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_dir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/runtime&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data_root = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/opt/memoh/data&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Пустое значение означает стандартное обнаружение окружения Docker: DOCKER_HOST,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># DOCKER_TLS_VERIFY, DOCKER_CERT_PATH или сокет по умолчанию для платформы.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Бэкенд Docker обращается к Docker Engine через стандартное окружение Docker. Он рассчитан на сервер Memoh, работающий прямо на хосте, или на окружение, где исходные пути bind-монтирования Docker указывают на реальные пути хоста.</p><p>Не переключайте стандартную установку Docker Compose с <code>containerd</code> на <code>docker</code>, если вы заодно не обеспечите валидные на хосте пути для <code>runtime_dir</code> и доступ к сокету Docker. Иначе контейнеры рабочих пространств могут создаваться без нужных им файлов bridge-рантайма.</p><h2 id="apple" tabindex="-1">Apple <a class="header-anchor" href="#apple" aria-label="Permalink to &quot;Apple&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;apple&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apple</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">socket_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">binary_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>Этот бэкенд предназначен для локального тестирования на macOS через socktainer и Apple Containerization. Он экспериментальный и не поддерживает сетевые сайдкары на основе провайдеров.</p><h2 id="дисплеи-browser-use-и-computer-use" tabindex="-1">Дисплей, Browser Use и Computer Use <a class="header-anchor" href="#дисплеи-browser-use-и-computer-use" aria-label="Permalink to &quot;Дисплей, Browser Use и Computer Use&quot;">​</a></h2><p>Контейнерные рабочие пространства могут предоставлять рантайм дисплея: Xvnc/RFB для рабочего стола пространства, браузер Chrome/Chromium с графическим интерфейсом (headed) и CDP, а также сессии WebRTC для панели Desktop в приложении.</p><p>Используйте этот путь, когда сайту нужен настоящий графический браузер. Headless Playwright по-прежнему доступен как обычная команда рабочего пространства, но Browser Use и Computer Use работают с графическим (headed) рабочим столом пространства.</p><p>Локальные рабочие пространства не дают той же изоляции контейнерного рабочего стола. Модель на уровне инструментов описана в <a href="./../guides/browser-computer-use.html">Browser / Computer Use</a>.</p><h2 id="сеть-и-оверлеи" tabindex="-1">Сеть и оверлеи <a class="header-anchor" href="#сеть-и-оверлеи" aria-label="Permalink to &quot;Сеть и оверлеи&quot;">​</a></h2><p>Сеть Bot устроена в два слоя:</p><ul><li>Сеть рантайма подключает рабочее пространство к базовой сети контейнера или пода.</li><li>Оверлейные провайдеры, такие как Tailscale и NetBird, добавляют необязательную приватную сеть для отдельного Bot.</li></ul><p>Возможности рантайма зависят от бэкенда:</p><table tabindex="0"><thead><tr><th>Бэкенд</th><th>Сеть рантайма</th><th>Оверлейные сайдкары</th><th>Устройства CDI</th><th>Дисплей в контейнере</th></tr></thead><tbody><tr><td><code>containerd</code></td><td>CNI</td><td>Да</td><td>Да</td><td>Да</td></tr><tr><td><code>docker</code></td><td>Подключение к контейнерной сети Docker</td><td>Ограничены возможностями рантайма Docker</td><td>Нет</td><td>Да, когда доступны файлы рантайма и пакеты в образе</td></tr><tr><td><code>apple</code></td><td>Базовый локальный рантайм</td><td>Нет</td><td>Нет</td><td>Ограниченно</td></tr><tr><td><code>local</code></td><td>Сеть хоста</td><td>Нет</td><td>Только на уровне хоста</td><td>Без контейнерного рабочего стола</td></tr></tbody></table><p>Настройки оверлейного провайдера задаются для каждого Bot в приложении, а не в глобальном TOML-файле. Глобальный бэкенд всё равно важен: он определяет, какой оверлейный драйвер сможет работать.</p><h2 id="устроиства-cdi-проброс-gpu" tabindex="-1">Устройства CDI (проброс GPU) <a class="header-anchor" href="#устроиства-cdi-проброс-gpu" aria-label="Permalink to &quot;Устройства CDI (проброс GPU)&quot;">​</a></h2><p>Чтобы пробросить устройства хоста в контейнерное рабочее пространство через <strong>CDI</strong> (чаще всего это GPU), настройте их у нужного Bot в разделе <strong>Workspace</strong> (рабочее пространство) → <strong>Advanced</strong>. Заниматься этим стоит, только когда внутри рабочего пространства действительно нужны задачи CUDA/ROCm.</p><h3 id="настроика" tabindex="-1">Настройка <a class="header-anchor" href="#настроика" aria-label="Permalink to &quot;Настройка&quot;">​</a></h3><ol><li>Откройте вкладку <strong>Workspace</strong>; если контейнера ещё нет, сначала создайте его кнопкой <strong>Create</strong>.</li><li>Разверните <strong>Advanced</strong>, включите <strong>GPU</strong> и перечислите имена устройств в <strong>CDI devices</strong> — по одному в строке или через запятую: <ul><li><code>nvidia.com/gpu=0</code>, <code>nvidia.com/gpu=all</code></li><li><code>amd.com/gpu=0</code>, <code>amd.com/gpu=all</code></li></ul></li></ol><h3 id="требования-к-хосту" tabindex="-1">Требования к хосту <a class="header-anchor" href="#требования-к-хосту" aria-label="Permalink to &quot;Требования к хосту&quot;">​</a></h3><p>Драйверы, инструменты вендора и спецификации CDI должны быть уже настроены на хосте. Обычно это означает:</p><ul><li>GPU уже работает на самом хосте</li><li>Спецификации лежат в <code>/etc/cdi</code> или <code>/var/run/cdi</code></li><li>Имена, которые вы вводите, совпадают с тем, что видит рантайм (проверьте через <code>nvidia-ctk cdi list</code> для NVIDIA и <code>amd-ctk cdi list</code> для AMD)</li></ul><p>Ошибка <code>unresolvable CDI devices</code> почти всегда означает несовпадение имён.</p><h3 id="примечания" tabindex="-1">Примечания <a class="header-anchor" href="#примечания" aria-label="Permalink to &quot;Примечания&quot;">​</a></h3><ul><li>CDI вступает в силу в момент <strong>создания</strong>: после изменения конфигурации контейнер обычно нужно <strong>пересоздать</strong> — остановка и запуск <strong>не</strong> заменяют подключённые устройства.</li><li>Образу всё равно нужны правильные библиотеки и инструменты пользовательского пространства, чтобы реально запускать софт CUDA/ROCm.</li><li>После создания вкладка <strong>Workspace</strong> показывает список подключённых устройств — по нему удобно сверяться.</li><li>Поддержка по бэкендам — в таблице выше: CDI поддерживает только <code>containerd</code>.</li></ul>`,42)])])}const E=a(n,[["render",l]]);export{c as __pageData,E as default};
